-- PT112-S1-Q20. Batch 04.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT112-S1-Q20$batch04$ AND q.stimulus=$batch04$Editorialist: To ensure justice in the legal system, citizens must be capable of criticizing anyone involved in determining the punishment of criminals. But when the legal system’s purpose is seen as deterrence, the system falls into the hands of experts whose specialty is to assess how potential lawbreakers are affected by the system’s punishments. Because most citizens lack knowledge about such matters, justice is not then ensured in the legal system.$batch04$ AND q.prompt=$batch04$The editorialist's argument requires assuming which one of the following?$batch04$ AND q.correct_choice=$batch04$E$batch04$) THEN RAISE EXCEPTION 'Question changed: PT112-S1-Q20'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch04$PT112-S1-Q20$batch04$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT112-S1-Q20'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT112-S1-Q20$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Conclusion$batch04$, $batch04$When the legal system's purpose is seen as deterrence, justice is not ensured.$batch04$), (1, $batch04$Evidence$batch04$, $batch04$Justice requires that citizens be capable of criticizing anyone involved in setting punishments. Under a deterrence approach, experts on how punishments affect potential lawbreakers run the system, and most citizens lack that knowledge.$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$The evidence says citizens lack *knowledge*. The requirement is that citizens be *capable of criticizing*. The argument needs a link between the two.$batch04$), (3, $batch04$Goal$batch04$, $batch04$A link: citizens without this knowledge cannot criticize the experts.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT112-S1-Q20$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$How citizens view justice does not affect whether they can criticize experts.$batch04$), ($batch04$B$batch04$, $batch04$The argument's requirement for justice is about citizen criticism, not the effect of punishment on criminals.$batch04$), ($batch04$C$batch04$, $batch04$The argument does not need justice to be the system's *primary* concern.$batch04$), ($batch04$D$batch04$, $batch04$The argument does not claim punishment and deterrence can't go together.$batch04$), ($batch04$E$batch04$, $batch04$Negate it: citizens *without* that knowledge *can* still criticize the experts. Then the requirement for justice is met, and the conclusion falls apart.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT112-S1-Q20$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
